    import sys
    input = sys.stdin.read
    x = input().strip()

    # Remove leading zeros
    while x[0] == '0':
        x = x[1:]

    # Remove trailing zeros after the decimal point
    if '.' in x:
        x = x.rstrip('0')
        if x[-1] == '.':
            x = x[:-1]

    # Handle special cases
    if x == '0':
        return '0'
    elif '.' not in x:
        return f'{x}E0'

    # Find the position of the first non-zero digit
    i = 0
    while x[i] == '0' or x[i] == '.':
        i += 1

    # Adjust the exponent and format the result
    exp = i - 1
    if exp == 0:
        return x
    else:
        return f'{x[:i]}E{exp}'

