import math

def simple_exponential_notation(x):
    if '.' in x:
        x = float(x)
    else:
        x = int(x)

    if x == 0:
        return "0"

    if x >= 10:
        exponent = math.floor(math.log10(x))
        a = x / (10 ** exponent)
    elif 0 < x < 1:
        exponent = -math.ceil(math.log10(x))
        a = x * (10 ** -exponent)
    else:
        return str(x)

    if a.is_integer():
        a = int(a)
        exponent_str = "" if exponent == 0 else f"E{exponent}"
    else:
        a_str = str(a).rstrip('0').rstrip('.')
        exponent_str = "" if exponent == 0 else f"E{exponent}"

    return f"{a_str}{exponent_str}"

